local GachaponStepNode = Class("GachaponStepNode")
local CommonCurrencyNode = "Game.Behaviours.CommonCurrencyNode"
local RootCount = 3
local cs_coroutine = require 'XLua.cs_coroutine'

function GachaponStepNode:__init()
    self.callBack = nil
    self.isPlay = false
    self.nodeEnv = nil
    self.pool = nil
    self.curTurn = nil
    self.currencyEnv = nil
end

function GachaponStepNode:__delete()
    self.pool = nil
    self.curTurn = nil
    self.currencyEnv = nil
    self.nodeEnv = nil
    self.isPlay = false
    self.controller = nil
end

function GachaponStepNode:SetCallBack(cb)
    self.callBack = cb
end

function GachaponStepNode:Awake()
    self:AddUIClick()
    self:InitNodeEnv()
end

function GachaponStepNode:AddUIClick()
    SetButtonAction(self.BtnStep,Bind(self,self.OnBtnStepClick))
    SetButtonAction(self.BtnTenNode,Bind(self,self.OnBtnTenNodeClick))
end


function GachaponStepNode:InitNodeEnv()
    self.nodeEnv = {}
    for i = 1, RootCount do
        local item = self["DiscType"..i]
        if isNotNull(item) then
            local env = CfUtils.GetLuaScr(item,"Game.Gachapon.GachaponStepDiscTypeCell")
            if isNotNull(env) then
                self.nodeEnv[i] = env
            end
        end
    end
    local env = CfUtils.GetLuaScr(self.ImgGoodIcon,CommonCurrencyNode)
    if isNotNull(env) then
        self.currencyEnv = env
    end
end

function GachaponStepNode:RefreshShow(pool, extra)
    self.pool = pool
    self.curTurn = self:GetCurStepType()
    self:RefreshCurTurnShow()
    self:RefreshStepShow()
    self:RefreshTimeShow()
    self:PlayShowAni(extra)
end

function GachaponStepNode:RefreshStepShow()
    local curStep = self:GetCurStep()
    for i, v in pairs(self.nodeEnv) do
        local data = self.pool.activity.rouletteInfo[i]
        if data then
            CfUtils.SetActive(v.controller.gameObject, data.stepType == self.curTurn)
            local isUnLock = data.stepType <= self.curTurn
            local curStep = isUnLock and curStep or 1
            local isMaxTurn = self:IsMaxTurn()
            v:RefreshShow(data, isUnLock, curStep, isMaxTurn)
        else
            CfUtils.SetActive(v.controller.gameObject, false)
        end
    end
end

function GachaponStepNode:SetCurStep()
    local index = self.curTurn - 100
    CfUtils.FillText(self.TxtNum,index)
end

function GachaponStepNode:SetCurCurrency()
    local consumeData = self:GetConsumeData()
    local step = self:GetCurStep()
    local consume = consumeData[step]
    local isFree = consume.goodsId == 0 or consume.num == 0
    CfUtils.SetActive(self.ImgGoodIcon.gameObject,not isFree)
    CfUtils.SetActive(self.ImgFree.gameObject, isFree)
    if not isFree then
        if isNotNull(self.currencyEnv) then
            self.currencyEnv:SetCurrencyShow(consume.goodsId,nil, "x"..consume.num)
        end
    end
    self:SetCurrencyBtnState()
end

function GachaponStepNode:SetBgState(isUnLock)
    local status = isUnLock and 1 or 2
    CfUtils.SetUISwitchImage(self.ImgBg,status)
end

function GachaponStepNode:SetRoundShow()
    local info = self:GetCurStepInfo()
    local isInfinite = info.totalRound == -1
    CfUtils.SetActive(self.RoundNum.gameObject,not isInfinite)
    CfUtils.SetActive(self.ImgInfinite.gameObject, isInfinite)
    if not isInfinite then
        CfUtils.FillText(self.RoundNum, table.concat({info.totalRound - info.finishRound ,"/", info.totalRound}))
    end
end

function GachaponStepNode:PlayShowAni(extra)
    self:RemoveAniCo()
    if isNotNull(extra) and not self.isPlay then
        self.aniCo = cs_coroutine.start(function()
            self.isPlay = true
            local data = string.split(extra,"_")
            if table.count(data) > 0 then
                local stepType = checkNumber(data[1])
                local stepNum = checkNumber(data[2])
                local curStepType = self:GetCurStepType()
                local aniName
                if curStepType > stepType then
                    aniName = string.format("GachaponVideo_StepChange%sTo%s",stepType - 100, curStepType - 100)
                else
                    local curStepNum = self:GetCurStep()
                    if curStepNum > stepNum then
                        aniName = "GachaponVideo_RotationStep"
                    else
                        aniName = "GachaponVideo_StepChangeResetOut"
                    end
                end
                cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.5))
                CfUtils.PlayAnimation(self.DiscGroup.gameObject, aniName)
            end
        end)
    end
end

function GachaponStepNode:RemoveAniCo()
    if isNotNull(self.aniCo) then
        cs_coroutine.stop(self.aniCo)
        self.aniCo = nil
    end
end

function GachaponStepNode:RefreshTimeShow()
    local pool = self.pool
    if (pool:IsValidActivity() and checkInt(pool.activity.endRemainTime) <= 0) or (pool.remainSeconds == 0) then
        if pool:IsValidActivity() then
            CfUtils.FillText(self.TxtTime, os.date("%Y.%m.%d", pool.activity.closeTime))
        else
            CfUtils.FillText(self.TxtTime, '')
        end
    else
        if pool:IsValidActivity() then
            CfUtils.FillText(self.TxtTime, GameUtils.CheckUTCTimeformat(GameUtils.l10nTimeData ("%Y.%m.%d", pool.activity.startTime).."-"..GameUtils.l10nTimeData("%Y.%m.%d %H:%M:%S",  pool.activity.endTime)))
        else
            CfUtils.FillText(self.TxtTime, '')
        end
    end
end

---获取当前轮盘
function GachaponStepNode:GetCurStepType()
    return self.pool.activity.stepType
end

---获取当前是第几步
function GachaponStepNode:GetCurStep()
    return self.pool.activity.stepNum
end

function GachaponStepNode:GetCurStepInfo()
    local turn = self.curTurn
    for i, v in pairs(self.pool.activity.rouletteInfo) do
        if v.stepType == turn then
            return v
        end
    end
    return nil
end

function GachaponStepNode:GetConsumeData()
    local turn = self.curTurn
    for i, v in pairs(self.pool.activity.rouletteInfo) do
        if v.stepType == turn then
            return v.consumeInfo
        end
    end
    return nil
end

function GachaponStepNode:RefreshCurTurnShow()
    self:SetCurStep()
    self:SetCurCurrency()
    self:SetRoundShow()
end

---设置抽奖按钮状态
function GachaponStepNode:SetCurrencyBtnState()
    local turn = self:GetCurStepType()
    local isUnLock = self.curTurn <= turn
    local state = isUnLock and 1 or 2
    CfUtils.SetUISwitchImage(self.ImgDisc, state)
    CfUtils.SetUISwitchImage(self.ImgBg, state)
    CfUtils.SetUISwitchText(self.Text, state)
    --local color = isUnLock and "#FFFFFF" or "#939393"
    self.currencyEnv:SetColorAndState(nil,state)
end


function GachaponStepNode:IsMaxTurn()
    local turn = self:GetCurStepType()
    local info
    for i, v in pairs(self.pool.activity.rouletteInfo) do
        if v.stepType == turn then
            info = v
            break
        end
    end
    if info.totalRound == -1 then
        return false
    end
    if info.totalRound - info.finishRound == 1 then
        return true
    end
    return false
end



---OnClick-----------------------------------------
function GachaponStepNode:OnBtnTenNodeClick()
    local turn = self:GetCurStepType()
    if turn == self.curTurn then
        if self.callBack then
            self.callBack()
        end
    end
end

function GachaponStepNode:OnBtnStepClick()
    local lastTurn = self.curTurn
    self.curTurn = self.curTurn + 1
    if (self.curTurn - 100) > table.count(self.pool.activity.rouletteInfo) then
        self.curTurn = self:GetCurStepType()
    end
    local index = lastTurn - 100
    CfUtils.SetActive(self.nodeEnv[index].controller.gameObject,false)
    index = self.curTurn - 100
    CfUtils.SetActive(self.nodeEnv[index].controller.gameObject,true)
    local aniName = string.format("GachaponVideo_StepChange%sTo%s",lastTurn - 100, index)
    CfUtils.PlayAnimation(self.DiscGroup, aniName)
    self:RefreshCurTurnShow()
end
---ClickEnd---------------------------------------------
function GachaponStepNode:OnDestroy()
    self:RemoveAniCo()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return GachaponStepNode